import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    last_was_key = False

    def strip_comment(value: str) -> str:
        in_quotes = False
        i = 0
        while i < len(value):
            c = value[i]
            if c == '"':
                in_quotes = not in_quotes
            elif not in_quotes and c in ';#' and i > 0 and value[i - 1] == ' ':
                return value[:i - 1]
            i += 1
        return value

    section_re = re.compile(r'^\s*\[([^\]]*)\]\s*$')
    ref_re = re.compile(r'\$\{([^}]+)\}')

    for line in text.splitlines():
        stripped = line.strip()

        # Rule 3: empty or comment lines
        if stripped == '' or (len(stripped) > 0 and stripped[0] in ';#'):
            last_was_key = False
            continue

        # Rule 1: section header
        m = section_re.match(line)
        if m:
            section_name = m.group(1).strip()
            current_section = section_name
            if current_section not in sections:
                sections[current_section] = {}
            last_was_key = False
            continue

        # Rule 6: continuation line
        if len(line) > 0 and line[0] in ' \t' and last_was_key:
            if current_section is not None and sections.get(current_section):
                last_key = list(sections[current_section].keys())[-1]
                sections[current_section][last_key] += '\n' + stripped
            last_was_key = True
            continue

        # Rule 2: key = value or key : value
        eq_pos = line.find('=')
        colon_pos = line.find(':')

        if eq_pos != -1 or colon_pos != -1:
            if eq_pos == -1:
                split_pos = colon_pos
            elif colon_pos == -1:
                split_pos = eq_pos
            else:
                split_pos = min(eq_pos, colon_pos)

            key = line[:split_pos].strip().lower()
            raw_value = line[split_pos + 1:]

            # Rule 4: strip inline comments
            raw_value = strip_comment(raw_value)
            raw_value = raw_value.strip()

            # Rule 5: double-quoted value
            if len(raw_value) >= 2 and raw_value.startswith('"') and raw_value.endswith('"'):
                value = raw_value[1:-1]
            else:
                value = raw_value.strip()

            # Rule 10: key before section header
            if current_section is None:
                raise ValueError("Key line before any section header")

            sections[current_section][key] = value
            last_was_key = True
            continue

        # Rule 10: malformed line
        raise ValueError(f"Malformed line: {line!r}")

    # Interpolation phase
    default_data = sections.get('DEFAULT', {})

    def get_raw(section: str, key: str) -> str:
        if section in sections and key in sections[section]:
            return sections[section][key]
        if key in default_data:
            return default_data[key]
        raise KeyError(f"Key '{key}' not found in section '{section}'")

    resolving: set[tuple[str, str]] = set()
    cache: dict[tuple[str, str], str] = {}

    def resolve(section: str, key: str) -> str:
        if (section, key) in cache:
            return cache[(section, key)]
        if (section, key) in resolving:
            raise ValueError(f"Cycle detected: {section}:{key}")

        raw = get_raw(section, key)
        resolving.add((section, key))
        try:
            result = _interpolate(raw, section)
        finally:
            resolving.discard((section, key))
        cache[(section, key)] = result
        return result

    def _interpolate(raw_value: str, current_section: str) -> str:
        def replace_ref(match: re.Match) -> str:
            ref = match.group(1)
            if ':' in ref:
                sec, key = ref.split(':', 1)
                sec = sec.strip()
                key = key.strip()
            else:
                sec = current_section
                key = ref.strip()
            return resolve(sec, key)

        return ref_re.sub(replace_ref, raw_value)

    result: dict[str, dict[str, str]] = {}
    for sec_name, sec_data in sections.items():
        if sec_name == 'DEFAULT':
            continue
        result[sec_name] = {}
        for key in sec_data:
            result[sec_name][key] = resolve(sec_name, key)

    return result
