import re


def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty or blank string")

    if re.fullmatch(r'\s*(?:\d+\s*[hms])*\s*', s, re.IGNORECASE) is None:
        raise ValueError("Invalid format")

    parts = list(re.finditer(r'(\d+)\s*([hms])', s, re.IGNORECASE))

    if not parts:
        raise ValueError("No duration parts found")

    order = {'h': 0, 'm': 1, 's': 2}
    last_idx = -1
    seen = set()
    total_seconds = 0

    for part in parts:
        value = int(part.group(1))
        unit = part.group(2).lower()

        if unit in seen:
            raise ValueError(f"Repeated unit: {unit}")
        seen.add(unit)

        idx = order[unit]
        if idx <= last_idx:
            raise ValueError(f"Units out of order")
        last_idx = idx

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds
