def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customers = {}

    for row in rows:
        name = row.get("customer", "")
        if not isinstance(name, str):
            continue
        name = name.strip()
        if not name:
            continue

        amount_raw = row.get("amount", "")
        if not isinstance(amount_raw, str):
            continue

        try:
            cleaned = amount_raw.strip().replace(",", "").replace("$", "")
            amount = float(cleaned)
        except (ValueError, TypeError):
            continue

        key = name.lower()
        if key not in customers:
            customers[key] = [name, 0.0]
        customers[key][1] += amount

    result = [(name, round(total, 2)) for name, total in customers.values()]
    result.sort(key=lambda x: (-x[1], x[0]))

    return result[:n]
